  assert.deepEqual(d.distribution.map((e) => [e.value, e.weight]), [[5, 3], [9, 1]]);
  assert.equal(d.max, 9);
  assert.equal(d.min, 5);
  assert.equal(d.distribution.at(-1)!.cum, 1);
  assert.throws(() => buildDist([[1, 0]]));
  assert.throws(() => buildDist([]));
});

